2	const base=path.dirname(fileURLToPath(import.meta.url)),root=path.resolve(base,'../..'),[phase,action,projectText,fromText,toText,purpose='full-reading',indexText]=process.argv.slice(2);assert.match(phase??'',/^[a-z][a-z0-9-]*$/);assert.equal(action,'read');const project=path.resolve(projectText),relative=path.relative(base,project);assert.ok(relative&&!path.isAbsolute(relative)&&!relative.startsWith('..'));const from=Number(fromText),to=Number(toText);assert.ok(Number.isInteger(from)&&from>=1&&Number.isInteger(to)&&to>=from&&to-from<3,'Read 1–3 chapters with sufficient visible output budget');const index=JSON.parse(fs.readFileSync(indexText?path.resolve(indexText):path.join(project,'.writer/state.json'))),dir=path.join(base,phase),listFile=path.join(dir,'readings.json');fs.mkdirSync(dir,{recursive:true});const readings=fs.existsSync(listFile)?JSON.parse(fs.readFileSync(listFile)):[];assert.ok(Array.isArray(readings));
3	for(let n=from;n<=to;n++){const unit=index.units.find(u=>u.unit===n);assert.ok(unit,'Index must contain requested unit '+n);assert.ok(typeof unit.draft==='string'&&!path.isAbsolute(unit.draft)&&!unit.draft.includes('..'));const file=path.resolve(project,unit.draft);assert.ok(path.relative(project,file)&&!path.relative(project,file).startsWith('..'));const stat=fs.lstatSync(file);assert.ok(stat.isFile()&&!stat.isSymbolicLink());const bytes=fs.readFileSync(file),hash=crypto.createHash('sha256').update(bytes).digest('hex'),lines=bytes.toString('utf8').replace(/^\uFEFF/,'').split(/\r?\n/),version=path.join(dir,'read-versions',hash+'.md');fs.mkdirSync(path.dirname(version),{recursive:true});if(fs.existsSync(version))assert.deepEqual(fs.readFileSync(version),bytes);else fs.writeFileSync(version,bytes,{flag:'wx'});const record={at:new Date().toISOString(),purpose,unit:n,file,sha256:hash,bytes:bytes.length,from_line:1,to_line:lines.length,version:path.relative(dir,version).replaceAll('\\','/'),basis:'Exact copy frozen before emitting numbered stdout; actual event exposure and comprehension audited separately'};readings.push(record);fs.writeFileSync(listFile,JSON.stringify(readings,null,2)+'\n','utf8');console.log(JSON.stringify({file,sha256:hash,unit:n,bytes:bytes.length,lines:lines.length,purpose}));for(let i=0;i<lines.length;i++)console.log((i+1)+'\t'+lines[i]);console.log('END FILE');}
